#!/usr/bin/env bash
# E-MAILS DES MEMBRES réservés aux administrateurs + ADRESSE DU CLUB des instructeurs :
#   - tickets (boîte, détail, personnes à qui transmettre), fichiers des espaces de groupe, sélecteurs
#     d'instructeurs : un non-admin ne voit plus aucune adresse personnelle (repli sur le nom / « Membre ») ;
#   - nouveau champ User.clubEmail (migration), saisi par un admin dans la fiche d'un membre ;
#     domaine imposé = celui de l'adresse de contact des Réglages (akfc.fr) ;
#   - page des instructeurs : l'adresse du club s'affiche pour les membres connectés uniquement ;
#   - doc : la règle ajoutée au chapitre « La frontière serveur / client ».
# Prérequis : apply-frontiere-serveur-client.sh.
# Usage (racine du repo, base locale démarrée) : bash apply-emails-membres-club.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"prisma/schema.prisma" 2>/dev/null | grep -qF "clubEmail"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "La frontière serveur / client" "apps/web/content/docs/dev/front/frontiere-serveur-client.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-frontiere-serveur-client.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/front/frontiere-serveur-client.mdx" "apps/web/src/app/(admin)/dashboard/tickets/page.tsx" "apps/web/src/app/(admin)/dashboard/users/[id]/edit/page.tsx" "apps/web/src/app/(public)/about/instructeurs/page.tsx" "packages/backend/src/modules/media/router.ts" "packages/backend/src/modules/tickets/ticketQueries.service.ts" "packages/backend/src/modules/users/router.ts" "prisma/schema.prisma")
CREATED=("prisma/migrations/20261208000000_user_club_email/migration.sql")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "prisma/migrations/20261208000000_user_club_email" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "clubEmail" "prisma/schema.prisma" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

